create schema app;
create table app."x.y" ("k.v" int primary key, note text, n int);
create table app.plain (id int primary key, ref int references app."x.y" ("k.v"));
create type app."en.um" as enum ('a', 'b');
create type app."co.mp" as (a int, b text);
create domain app."do.m" as int check (value > 0);
create sequence app."se.q" owned by app."x.y".n;
create sequence app.plain_seq owned by app."x.y"."k.v";
create view app."v.w" as select "k.v" from app."x.y";
create materialized view app."m.v" as select "k.v" from app."x.y";
create function app."f.n"(a int) returns int language sql as $$select a$$;
create function app.std() returns int language sql return app."f.n"(1);
create procedure app."p.r"() language sql as $$select 1$$;
create aggregate app."ag.g"(int) (sfunc = int4pl, stype = int);
create collation app."co.ll" (locale = 'C');
create text search dictionary app."di.ct" (template = simple);
create text search configuration app."cf.g" (copy = simple);
create table app."pa.rt" (id int, k int) partition by list (k);
create table app."pa.rt1" partition of app."pa.rt" for values in (1);
create table app."ty.ped" of app."co.mp";
create table app."in.h" (extra int) inherits (app."x.y");
create table app.typed_cols (e app."en.um", d app."do.m", c app."co.mp", s text collate app."co.ll");
comment on table app."x.y" is 'dotted table';
comment on type app."en.um" is 'dotted enum';
comment on function app."f.n"(int) is 'dotted function';
create view app.uses as select * from app."v.w";
create function app."tr.f"() returns trigger language plpgsql as $$begin return new; end$$;
create trigger t before insert on app."x.y" for each row execute function app."tr.f"();
create index "x.y_note" on app."x.y" (note);
grant select on app."x.y" to public;
create publication "dot.pub" for table app."x.y";
create table app.seq_default (id int default nextval('app."se.q"'));
create function app."ev.f"() returns event_trigger language plpgsql as $$begin end$$;
create event trigger "dot.et" on ddl_command_end execute function app."ev.f"();
create domain app.dc as text collate app."co.ll";
create type app.cc as (a text collate app."co.ll");
alter text search configuration app."cf.g" alter mapping for asciiword with app."di.ct";
